import pandas as pd
import numpy as np
from scipy import stats

print("="*60)
print("COMPREHENSIVE ANALYSIS OF ALL AVAILABLE EXPERIMENTS")
print("="*60)

for exp_id in [1, 2, 5, 6, 7, 9, 10]:
    try:
        df = pd.read_csv(f"experiment_{exp_id}_csv")
        print(f"\n=== Experiment {exp_id} ===")
        print(f"Columns: {list(df.columns)}")
        print(f"Rows: {len(df)}")

        # Check if CapacityRetention is present
        if 'CapacityRetention' in df.columns:
            print(f"Mean CapacityRetention: {df['CapacityRetention'].mean():.3f} +/- {df['CapacityRetention'].std():.3f}")

        # Show numeric correlations with CapacityRetention
        if 'CapacityRetention' in df.columns:
            numeric_cols = df.select_dtypes(include=[np.number]).columns
            corr_with_outcome = df[numeric_cols].corr()['CapacityRetention'].drop('CapacityRetention').sort_values(ascending=False)
            print(f"Correlations with CapacityRetention:\n{corr_with_outcome.round(3)}")

        # Show unique values for categorical columns (likely interventions)
        for col in df.columns:
            if df[col].nunique() <= 5 and df[col].dtype != 'float64':
                print(f"  {col} unique values: {df[col].unique()}")
            elif df[col].nunique() == 1:
                print(f"  {col} CONSTANT at {df[col].iloc[0]}")

    except FileNotFoundError:
        print(f"\nExperiment {exp_id}: FILE NOT FOUND")
    except Exception as e:
        print(f"\nExperiment {exp_id}: ERROR - {e}")
